import collections
import pytest

marked = collections.Counter()
modules = []


def pytest_collectreport(report):
    if report.skipped:
        modules.append((report.nodeid, str(report.longrepr[-1]) if isinstance(report.longrepr, tuple) else str(report.longrepr)))


def pytest_collection_modifyitems(items):
    for item in items:
        for m in item.iter_markers("skipif"):
            if m.args and m.args[0] is True:
                marked[(item.nodeid.split("::")[0], m.kwargs.get("reason"))] += 1
                break
        for m in item.iter_markers("skip"):
            marked[(item.nodeid.split("::")[0], m.kwargs.get("reason"))] += 1


@pytest.hookimpl(trylast=True)
def pytest_collection_finish(session):
    print("\nMODULES SKIPPED AT COLLECTION:")
    for nodeid, reason in modules:
        print(f"  {nodeid}: {reason}")
    print("ITEMS WITH A TRUE SKIP MARK:", sum(marked.values()))
    for (path, reason), n in sorted(marked.items()):
        print(f"  {n:3d}  {path}: {reason}")
EOF
